SELECT CASE WHEN s.rating >= 4.1 THEN 'high' WHEN s.rating >= 2.6 THEN 'mid' ELSE 'low' END AS rating_bucket, AVG(i.quantity) AS avg_quantity, MIN(i.last_restock) AS min_last_restock FROM inventory i JOIN products p ON p.id = i.product_id JOIN suppliers s ON p.supplier_id = s.id WHERE p.supplier_id = 9 GROUP BY CASE WHEN s.rating >= 4.1 THEN 'high' WHEN s.rating >= 2.6 THEN 'mid' ELSE 'low' END
